#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAXN 2005
#define INF -1e9

int N, Q;
int a[MAXN], b[MAXN];

typedef struct {
    int dp[2][2]; // dp[b1][b2] for balances 0 or 1 (since max balance diff small)
} Node;

Node seg[4*MAXN];
int base_contribution;

Node merge(Node left, Node right) {
    Node res;
    for (int i=0;i<2;i++) for(int j=0;j<2;j++) res.dp[i][j] = INF;
    for (int i1=0;i1<2;i1++) for(int j1=0;j1<2;j1++) if(left.dp[i1][j1] > INF) {
        for (int i2=0;i2<2;i2++) for(int j2=0;j2<2;j2++) if(right.dp[i2][j2] > INF) {
            int ni = i1 + i2;
            int nj = j1 + j2;
            if (ni < 2 && nj < 2) {
                int val = left.dp[i1][j1] + right.dp[i2][j2];
                if (val > res.dp[ni][nj]) res.dp[ni][nj] = val;
            }
        }
    }
    return res;
}

Node make_leaf(int idx) {
    Node res;
    for (int i=0;i<2;i++) for(int j=0;j<2;j++) res.dp[i][j] = INF;
    // match both '('  -> balances +1,+1
    if (1 < 2) res.dp[1][1] = a[idx] - b[idx];
    // mismatch: (+1,-1) or (-1,+1) -> balance change 0,0
    res.dp[0][0] = 0; // choosing mismatch gives 0 extra
    return res;
}

void build(int node, int l, int r) {
    if (l == r) {
        seg[node] = make_leaf(l);
        return;
    }
    int mid = (l+r)/2;
    build(node*2, l, mid);
    build(node*2+1, mid+1, r);
    seg[node] = merge(seg[node*2], seg[node*2+1]);
}

void update(int node, int l, int r, int idx) {
    if (l == r) {
        seg[node] = make_leaf(l);
        return;
    }
    int mid = (l+r)/2;
    if (idx <= mid) update(node*2, l, mid, idx);
    else update(node*2+1, mid+1, r, idx);
    seg[node] = merge(seg[node*2], seg[node*2+1]);
}

