        int len = 2*N;
        // dp[j][k] = max beauty, j = open in s, k = open in t
        const long long NEG = -1e18;
        vector<vector<long long>> dp(N+1, vector<long long>(N+1, NEG));
        dp[0][0] = 0;

        for (int i = 1; i <= len; i++) {
            vector<vector<long long>> ndp(N+1, vector<long long>(N+1, NEG));
            int rem = len - i; // remaining after this position
            for (int j = 0; j <= N; j++) {
                for (int k = 0; k <= N; k++) {
                    if (dp[j][k] == NEG) continue;
                    // try 4 combinations
                    // ds, dt in {+1, -1}
                    for (int ds : {1, -1}) {
                        for (int dt : {1, -1}) {
                            int nj = j + ds, nk = k + dt;
                            if (nj < 0 || nk < 0) continue;
                            if (nj > rem || nk > rem) continue; // can't close enough
                            long long val = (ds == dt) ? a[i] : b[i];
                            if (ndp[nj][nk] < dp[j][k] + val)
                                ndp[nj][nk] = dp[j][k] + val;
