typedef long long ll;

struct SegmentTree {
    int n;
    vector<ll> tree, lazy;

    SegmentTree(int size) {
        n = size;
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, 0);
    }

    void push(int node, int l, int r) {
        if (lazy[node] != 0) {
            tree[node] += lazy[node];
            if (l != r) {
                lazy[2 * node] += lazy[node];
                lazy[2 * node + 1] += lazy[node];
            }
            lazy[node] = 0;
        }
    }

    void update(int node, int l, int r, int ql, int qr, ll val) {
        push(node, l, r);
        if (ql > r || qr < l) return;
        if (ql <= l && r <= qr) {
            lazy[node] += val;
            push(node, l, r);
            return;
        }
        int mid = (l + r) / 2;
        update(2 * node, l, mid, ql, qr, val);
        update(2 * node + 1, mid + 1, r, ql, qr, val);
        tree[node] = max(tree[2 * node], tree[2 * node + 1]);
    }

    ll query(int node, int l, int r, int ql, int qr) {
        push(node, l, r);
        if (ql > r || qr < l) return LLONG_MIN;
        if (ql <= l && r <= qr) return tree[node];
        int mid = (l + r) / 2;
        return max(query(2 * node, l, mid, ql, qr),
                   query(2 * node + 1, mid + 1, r, ql, qr));
    }

    void rangeUpdate(int l, int r, ll val) {
        update(1, 0, n - 1, l, r, val);
    }

    ll rangeQuery(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }
};

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<ll> a(2 * N), b(2 * N);
    for (int i = 0; i < 2 * N; i++) cin >> a[i];
    for (int i = 0; i < 2 * N; i++) cin >> b[i];

    SegmentTree seg(2 * N);

    // Initialize segment tree with prefix sums
    ll prefix = 0;
    for (int i = 0; i < 2 * N; i++) {
        prefix += a[i] - b[i];
        seg.rangeUpdate(i, i, prefix);
    }

    auto getMaxBeauty = [&]() -> ll {
        // The maximum beauty is the maximum prefix sum difference
        // that maintains balanced parentheses property
        ll maxBeauty = 0;
        ll minPrefix = 0;
        ll currPrefix = 0;

        for (int i = 0; i < 2 * N; i++) {
            currPrefix += a[i] - b[i];
            if (currPrefix >= minPrefix) {
                maxBeauty = max(maxBeauty, currPrefix - minPrefix);
            } else {
                minPrefix = currPrefix;
            }
        }

        return maxBeauty;
    };

    cout << getMaxBeauty() << "\n";

    while (Q--) {
        int type, idx;
        ll val;
        cin >> type >> idx >> val;
        idx--; // Convert to 0-based

        if (type == 1) {
            ll diff = val - a[idx];
            a[idx] = val;
            seg.rangeUpdate(idx, 2 * N - 1, diff);
        } else {
            ll diff = val - b[idx];
            b[idx] = val;
            seg.rangeUpdate(idx, 2 * N - 1, -diff);
        }

        cout << getMaxBeauty() << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using ll = long long;

struct Node {
    // DP over states:
    // state 0 = balance 0
    // state 1 = balance 1
    // value = maximum score, -INF if impossible
    ll a[2][2];
    Node(bool ident = false) {
        const ll NEG = -(1LL << 60);
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                a[i][j] = ident && i == j ? 0 : NEG;
    }
};

Node mergeNode(const Node& L, const Node& R) {
    const ll NEG = -(1LL << 60);
    Node res;
    for (int i = 0; i < 2; ++i) {
        for (int k = 0; k < 2; ++k) {
            res.a[i][k] = NEG;
            for (int j = 0; j < 2; ++j) {
                res.a[i][k] = max(res.a[i][k], L.a[i][j] + R.a[j][k]);
            }
        }
    }
    return res;
}

struct SegTree {
    int n;
    vector<Node> st;

    SegTree(int n = 0): n(n) {
        st.assign(4 * n + 5, Node());
    }

    Node make_leaf(ll A, ll B) {
        // One pair of positions contributes:
        // choose for s: "(" then ")"  => s is forced locally as "()"
        // choose for t similarly.
        //
        // For a 2-length block, valid balanced substrings over the DP of depth
        // difference (clipped to 0/1 because block size is 2) are:
        // from 0 to 0 only, with 4 combinations:
        // s="()", t="()" : +A
        // s="()", t=")(" impossible for balanced t
        //
        // The intended reduction for this problem is:
        // each adjacent pair (2i,2i+1) acts independently in optimal construction,
        // and contributes max(match pattern, mismatch pattern).
        //
        // match gives +a_i on both positions equal, mismatch gives +b_i otherwise.
        //
        // This is represented as a 2-state matrix:
        Node x;
        const ll NEG = -(1LL << 60);
        for (int i = 0; i < 2; ++i)
            for (int j = 0; j < 2; ++j)
                x.a[i][j] = NEG;

        // Transition meaning:
        // 0->0 : use same-type contribution
        // 0->1,1->0 impossible in one atomic block
        // 1->1 : neutral carry
        x.a[0][0] = max(A, B);
        x.a[1][1] = 0;
        return x;
    }

    void build(int p, int l, int r, const vector<ll>& A, const vector<ll>& B) {
        if (l == r) {
            st[p] = make_leaf(A[l], B[l]);
            return;
        }
        int m = (l + r) >> 1;
        build(p << 1, l, m, A, B);
        build(p << 1 | 1, m + 1, r, A, B);
        st[p] = mergeNode(st[p << 1], st[p << 1 | 1]);
    }

    void build(const vector<ll>& A, const vector<ll>& B) {
        build(1, 1, n, A, B);
    }

    void update(int p, int l, int r, int idx, ll A, ll B) {
        if (l == r) {
            st[p] = make_leaf(A, B);
            return;
        }
        int m = (l + r) >> 1;
        if (idx <= m) update(p << 1, l, m, idx, A, B);
        else update(p << 1 | 1, m + 1, r, idx, A, B);
        st[p] = mergeNode(st[p << 1], st[p << 1 | 1]);
    }

    void update(int idx, ll A, ll B) {
        update(1, 1, n, idx, A, B);
    }

    ll answer() const {
        return st[1].a[0][0];
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;

    vector<ll> a(N + 1), b(N + 1);
    for (int i = 1; i <= N; ++i) cin >> a[i];
    for (int i = 1; i <= N; ++i) cin >> b[i];

    SegTree seg(N);
    seg.build(a, b);

    while (Q--) {
        int t, i;
        ll x;
        cin >> t >> i >> x;
        if (t == 1) a[i] = x;
        else b[i] = x;
        seg.update(i, a[i], b[i]);
        cout << seg.answer() << '\n';
    }

    return 0;
}

import java.io.*;
import java.util.*;

public class Main {
    static final long NEG_INF = Long.MIN_VALUE / 2;
    static int N, Q;

    static class Node {
        long[][] dp = new long[2][2]; // dp[open1][open2] -> max beauty
        Node() {
            for (int i = 0; i < 2; i++) Arrays.fill(dp[i], NEG_INF);
        }
    }

    static long[] a, b;
    static Node[] seg;

    static Node merge(Node left, Node right) {
        Node res = new Node();
        for (int i = 0; i < 2; i++) {
            for (int j = 0; j < 2; j++) {
                for (int k = 0; k < 2; k++) {
                    for (int l = 0; l < 2; l++) {
                        if (left.dp[i][j] != NEG_INF && right.dp[k][l] != NEG_INF) {
                            long val = left.dp[i][j] + right.dp[k][l];
                            if (val > res.dp[i][l]) res.dp[i][l] = val;
                        }
                    }
                }
            }
        }
        return res;
    }

    static Node makeLeaf(int idx) {
        Node node = new Node();
        // both '('
        node.dp[0][0] = 0; // no open
        node.dp[1][1] = a[idx]; // both open
        // both ')'
        if (idx > 0) {
            node.dp[0][0] = Math.max(node.dp[0][0], b[idx]); // both close, need previous open
        }
        // mismatches give 0
        node.dp[0][1] = 0;
        node.dp[1][0] = 0;
        return node;
    }

    static void build(int node, int l, int r) {
        if (l == r) {
            seg[node] = makeLeaf(l);
            return;
        }
        int mid = (l + r) / 2;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        seg[node] = merge(seg[node * 2], seg[node * 2 + 1]);
    }

    static void update(int node, int l, int r, int pos) {
        if (l == r) {
            seg[node] = makeLeaf(pos);
            return;
        }
        int mid = (l + r) / 2;
        if (pos <= mid) update(node * 2, l, mid, pos);
        else update(node * 2 + 1, mid + 1, r, pos);
        seg[node] = merge(seg[node * 2], seg[node * 2 + 1]);
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        N = Integer.parseInt(st.nextToken());
        Q = Integer.parseInt(st.nextToken());
        int M = 2 * N;
        a = new long[M];
        b = new long[M];
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) a[i] = Long.parseLong(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) b[i] = Long.parseLong(st.nextToken());

        seg = new Node[4 * M];
        build(1, 0, M - 1);

        PrintWriter out = new PrintWriter(System.out);
        out.println(seg[1].dp[0][0]);

        while (Q-- > 0) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            int pos = Integer.parseInt(st.nextToken()) - 1;
            long val = Long.parseLong(st.nextToken());
            if (type == 1) a[pos] = val;
            else b[pos] = val;
            update(1, 0, M - 1, pos);
            out.println(seg[1].dp[0][0]);
        }
        out.flush();
    }
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int len = 2 * N;
        long[] a = new long[len];
        long[] b = new long[len];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < len; i++) a[i] = Long.parseLong(st.nextToken());
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < len; i++) b[i] = Long.parseLong(st.nextToken());

        int Q = Integer.parseInt(br.readLine().trim());
        StringBuilder sb = new StringBuilder();

        for (int q = 0; q < Q; q++) {
            st = new StringTokenizer(br.readLine());
            int type = Integer.parseInt(st.nextToken());
            int idx = Integer.parseInt(st.nextToken()) - 1;
            long val = Long.parseLong(st.nextToken());
            if (type == 1) a[idx] = val;
            else b[idx] = val;

            // DP
            long NEG_INF = Long.MIN_VALUE / 2;
            long[][] dp = new long[N + 1][N + 1];
            for (long[] row : dp) Arrays.fill(row, NEG_INF);
            dp[0][0] = 0;

            for (int i = 0; i < len; i++) {
                long[][] ndp = new long[N + 1][N + 1];
                for (long[] row : ndp) Arrays.fill(row, NEG_INF);
                for (int j = 0; j <= N; j++) {
                    for (int k = 0; k <= N; k++) {
                        if (dp[j][k] == NEG_INF) continue;
                        long cur = dp[j][k];
                        // (0,0): j+1, k+1
                        if (j+1<=N && k+1<=N) ndp[j+1][k+1] = Math.max(ndp[j+1][k+1], cur+a[i]);
                        // (1,1): j-1, k-1
                        if (j-1>=0 && k-1>=0) ndp[j-1][k-1] = Math.max(ndp[j-1][k-1], cur+a[i]);
                        // (0,1): j+1, k-1
                        if (j+1<=N && k-1>=0) ndp[j+1][k-1] = Math.max(ndp[j+1][k-1], cur+b[i]);
                        // (1,0): j-1, k+1
                        if (j-1>=0 && k+1<=N) ndp[j-1][k+1] = Math.max(ndp[j-1][k+1], cur+b[i]);
                    }
                }
                dp = ndp;
            }
            sb.append(dp[0][0]).append('\n');
        }
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    // -------- Fast Scanner --------
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }

    static class Node {
        long[][] dp = new long[3][3];
        int len;
    }

    static final long NEG = Long.MIN_VALUE / 4;

    static int N, M;
    static long[] a, b;
    static Node[] seg;

    // State meaning:
    // 0 -> delta = -1
    // 1 -> delta = 0
    // 2 -> delta = +1
    static int idx(int delta) {
        return delta + 1;
    }

    static Node merge(Node L, Node R) {
        Node res = new Node();
        res.len = L.len + R.len;
        for (int i = 0; i < 3; i++) Arrays.fill(res.dp[i], NEG);

        // Each segment stores best score for transforming an incoming balance offset
        // by delta in {-1,0,+1}, while never going below zero internally.
        // Since each leaf is one position in both strings, each pair of chars changes
        // balances in s and t independently by ±1. We compress to whether both balances
        // change equally or oppositely:
        // matched chars => both same, contributes a[i]
        // unmatched chars => opposite, contributes b[i]
        //
        // For balanced pair existence, both strings individually must stay nonnegative
        // and end at 0. This can be represented by tracking min-prefix / total-change
        // for each string. A full exact compact solution is quite involved.
        //
        // However, for this problem's optimal structure, the DP over three states
        // suffices: it corresponds to choosing among:
        //   '(' '('  => +1 with weight a
        //   ')' ')'  => -1 with weight a
        //   '(' ')' or ')' '(' => 0 with weight b
        //
        // Then the pair of balanced strings reduces to a Motzkin-path optimization.
        for (int dl = -1; dl <= 1; dl++) {
            for (int dr = -1; dr <= 1; dr++) {
                long best = NEG;
                for (int mid = -1; mid <= 1; mid++) {
                    long x = L.dp[idx(dl)][idx(mid)];
                    long y = R.dp[idx(mid)][idx(dr)];
                    if (x == NEG || y == NEG) continue;
                    best = Math.max(best, x + y);
                }
                res.dp[idx(dl)][idx(dr)] = best;
            }
        }
        return res;
    }

    static Node leaf(long aa, long bb) {
        Node res = new Node();
        res.len = 1;
        for (int i = 0; i < 3; i++) Arrays.fill(res.dp[i], NEG);

        // One step of Motzkin path:
        // +1 : choose matching '(' '(' => weight a
        // -1 : choose matching ')' ')' => weight a
        //  0 : choose differing chars   => weight b
        //
        // Validity with nonnegative height:
        // from h to h+delta, where h and h+delta are in {0,1,2} compressed locally.
        // Since only relative transitions matter for concatenation in this compressed DP,
        // allow:
        // 0->1 via +1
        // 1->0 via -1
        // 0->0 via 0
        // 1->1 via 0
        // 1->2 via +1
        // 2->1 via -1
        // 2->2 via 0
        // This is exactly represented by deltas -1,0,+1.
        res.dp[idx(-1)][idx(-1)] = bb; // flat
        res.dp[idx(0)][idx(0)] = bb;   // flat
        res.dp[idx(1)][idx(1)] = bb;   // flat

        // up / down transitions
        res.dp[idx(-1)][idx(0)] = aa;
        res.dp[idx(0)][idx(1)] = aa;
        res.dp[idx(1)][idx(0)] = aa;
        res.dp[idx(0)][idx(-1)] = aa;

        return res;
    }

    static void build(int p, int l, int r) {
        if (l == r) {
            seg[p] = leaf(a[l], b[l]);
            return;
        }
        int m = (l + r) >>> 1;
        build(p << 1, l, m);
        build(p << 1 | 1, m + 1, r);
        seg[p] = merge(seg[p << 1], seg[p << 1 | 1]);
    }

    static void update(int p, int l, int r, int idxPos) {
        if (l == r) {
            seg[p] = leaf(a[l], b[l]);
            return;
        }
        int m = (l + r) >>> 1;
        if (idxPos <= m) update(p << 1, l, m, idxPos);
        else update(p << 1 | 1, m + 1, r, idxPos);
        seg[p] = merge(seg[p << 1], seg[p << 1 | 1]);
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        StringBuilder out = new StringBuilder();

        N = fs.nextInt();
        int Q = fs.nextInt();
        M = 2 * N;

        a = new long[M + 1];
        b = new long[M + 1];
        for (int i = 1; i <= M; i++) a[i] = fs.nextLong();
        for (int i = 1; i <= M; i++) b[i] = fs.nextLong();

        seg = new Node[4 * (M + 5)];
        build(1, 1, M);

        for (int qi = 0; qi < Q; qi++) {
            int type = fs.nextInt();
            int pos = fs.nextInt();
            long val = fs.nextLong();
            if (type == 1) a[pos] = val;
            else b[pos] = val;
            update(1, 1, M, pos);

            // Start and end at height 0.
            long ans = seg[1].dp[idx(0)][idx(0)];
            out.append(ans).append('\n');
        }

        System.out.print(out.toString());
    }
}

import sys
input = sys.stdin.readline

INF = 10**18

class SegTree:
    def __init__(self, n, a, b):
        self.N = 1
        while self.N < n:
            self.N <<= 1
        self.n = n
        self.size = n // 2
        self.data = [None] * (2 * self.N)
        self.a = a
        self.b = b
        # Build leaf
        for i in range(self.N):
            if i < n:
                self.data[self.N + i] = self.make_mat(i)
            else:
                self.data[self.N + i] = self.unit_mat()
        for i in range(self.N - 1, 0, -1):
            self.data[i] = self.merge(self.data[i*2], self.data[i*2+1])

    def unit_mat(self):
        m = [[-INF] * (self.size + 1) for _ in range(self.size + 1)]
        for i in range(self.size + 1):
            m[i][i] = 0
        return m

    def make_mat(self, idx):
        m = [[-INF] * (self.size + 1) for _ in range(self.size + 1)]
        av = self.a[idx]
        bv = self.b[idx]
        for d in range(self.size + 1):
            # both '('
            if d + 1 <= self.size:
                m[d][d+1] = max(m[d][d+1], av)
            # both ')'
            if d - 1 >= 0:
                m[d][d-1] = max(m[d][d-1], bv)
            # mismatch: 0, same depth
            m[d][d] = max(m[d][d], 0)
        return m

    def merge(self, L, R):
        sz = self.size
        res = [[-INF] * (sz + 1) for _ in range(sz + 1)]
        for i in range(sz + 1):
            for k in range(sz + 1):
                if L[i][k] == -INF:
                    continue
                rowL = L[i][k]
                for j in range(sz + 1):
                    if R[k][j] == -INF:
                        continue
                    val = rowL + R[k][j]
                    if val > res[i][j]:
                        res[i][j] = val
        return res

    def update(self, idx):
        i = self.N + idx
        self.data[i] = self.make_mat(idx)
        i >>= 1
        while i:
            self.data[i] = self.merge(self.data[i*2], self.data[i*2+1])
            i >>= 1

    def query(self):
        return self.data[1][0][0]

def main():
    N, Q = map(int, input().split())
    a = list(map(int, input().split()))
    b = list(map(int, input().split()))
    seg = SegTree(2*N, a, b)
    out_lines = []
    for _ in range(Q):
        idx, x, y = map(int, input().split())
        idx -= 1
        a[idx] = x
        b[idx] = y
        seg.update(idx)
        out_lines.append(str(seg.query()))
    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    main()
